messages.content:
{
  "justification_nom": "Règle 3 violée. Tag correct : ABONNEMENT_SUPPRIMER.",
  "intention_nommee": "ABONNEMENT_SUPPRIMER"
}

{
  "justification_nom": "Format infinitif respecté pour l'action de commande alimentaire.",
  "intention_nommee": "RESTAURATION_COMMANDER"
}

{
  "justification_nom": "Domaine généralisé respectant la règle 4 (pas de moyen comme domaine).",
  "intention_nommee": "TRANSPORT_RESERVER"
}

{
  "justification_nom": "Verbe à l'infinitif correct (CREER, pas CREE) pour la création d'événement.",
  "intention_nommee": "CALENDRIER_CREER"
}

{
  "justification_nom": "Verbe inexistant/non-standard. Doit être RADIO_JOUER.",
  "intention_nommee": "RADIO_JOUER"
}

{
  "justification_nom": "Règles 3 et 7 violées. Tag correct : RESEAUX_PUBLIER.",
  "intention_nommee": "RESEAUX_PUBLIER"
}

{
  "justification_nom": "Domaine et action corrects.",
  "intention_nommee": "TRADUCTION_QUERY"
}

{
  "justification_nom": "Règle 1 violée : pas un infinitif propre. Tag correct : LISTE_SUPPRIMER.",
  "intention_nommee": "LISTE_SUPPRIMER"
}

{
  "justification_nom": "Domaine RADIO généralisé malgré les noms de stations spécifiques.",
  "intention_nommee": "RADIO_JOUER"
}

{
  "justification_nom": "Faux domaine. La requête porte strictement sur l'heure. Le tag correct est HEURE_QUERY.",
  "intention_nommee": "HEURE_QUERY"
}

{
  "justification_nom": "Domaine global valide (ECONOMIE) ou DEVISE_QUERY, avec le suffixe correct.",
  "intention_nommee": "ECONOMIE_QUERY"
}

{
  "justification_nom": "Action CREER infinitive sur le domaine ALARME.",
  "intention_nommee": "ALARME_CREER"
}

{
  "justification_nom": "L'action 'PASSER' est floue. La taxonomie standard pour cela est MEDIA_SUIVANT ou MEDIA_CONTROLER.",
  "intention_nommee": "MEDIA_SUIVANT"
}

{
  "justification_nom": "Domaine généralisé (TRANSPORT) et verbe transactionnel approprié (RESERVER).",
  "intention_nommee": "TRANSPORT_RESERVER"
}

{
  "justification_nom": "Consultation valide, format correct.",
  "intention_nommee": "ALARME_QUERY"
}

{
  "justification_nom": "Ce n'est pas un QUERY (consultation) mais une écriture (POST). De plus, SOCIALMEDIA est un anglicisme. Doit être RESEAUX_PUBLIER.",
  "intention_nommee": "RESEAUX_PUBLIER"
}

{
  "justification_nom": "Domaine français RAPPEL et action de consultation (QUERY) correcte.",
  "intention_nommee": "RAPPEL_QUERY"
}

{
  "justification_nom": "Le terme DOMESTIQUE n'est pas le standard industriel habituel, on préfère DOMOTIQUE. Le tag optimal serait NETTOYAGE_COMMENCER ou DOMOTIQUE_ACTIVER.",
  "intention_nommee": "NETTOYAGE_COMMENCER"
}

{
  "justification_nom": "Même erreur : manque de généralisation du domaine. Doit être TRANSPORT_RESERVER.",
  "intention_nommee": "TRANSPORT_RESERVER"
}

{
  "justification_nom": "Consultation (QUERY) de l'état des alarmes.",
  "intention_nommee": "ALARME_QUERY"
}

{
  "justification_nom": "Domaine RESEAUX généralisé (pas TWITTER) avec action PUBLIER.",
  "intention_nommee": "RESEAUX_PUBLIER"
}
